(function(root){root.FishingScratchAudio={async create(){const A=window.AudioContext||window.webkitAudioContext;if(!A)throw Error('Web Audio unavailable');const c=new A();await c.resume();const master=c.createGain();master.gain.value=.10;master.connect(c.destination);function tone(f,t,d=.16,type='sine'){const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(f*.8,t+d);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.5,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.01)}function noise(t,d=.16){const b=c.createBuffer(1,Math.ceil(c.sampleRate*d),c.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.exp(-i/a.length*7);const s=c.createBufferSource(),f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=1400;s.buffer=b;s.connect(f);f.connect(master);s.start(t)}return{cue(name){const t=c.currentTime;if(name==='win'){[330,440,550].forEach((f,i)=>tone(f,t+i*.085,.28))}else if(name==='bite'){noise(t,.12);tone(150,t,.14,'triangle')}else{noise(t,.19);tone(220,t,.12,'triangle')}},close(){c.close()}}}}})(typeof window!=='undefined'?window:globalThis);
